import WeatherAnimations from "./WeatherAnimations";
import $ from "jquery";
import moment from "moment";
import {API} from "@/configs/configs";
import axios from "axios";
export default {
    name: 'Frost Weather App',
    props: {
        msg: String
    },
    data: () => ({
        weatherAnimations: null,
        weatherData: null,
        city: "",
        temperature: 0,
        isCelsius: true,
        temperatureSign: "°C",
        date: moment().format('MMMM Do YYYY'),
        sunrise: 0,
        sunset: 0,
        humidity: 0,
        pressure: 0,
        rain: 0,
        wind: {
            speed: 0,
            rotation: 0
        }
    }),
    created() {
    },
    mounted() {
        $(document).ready(()=>{
            this.weatherAnimations = new WeatherAnimations();
            // ⚙ initialize app
            this.weatherAnimations.init();
            // 👁 watch for window resize
            $(window).resize(()=>{
                this.weatherAnimations.onResize();
            });
            // 🏃 start animations
            window.requestAnimationFrame(()=>this.weatherAnimations.tick);
            this.getLocation().then(()=>{
                setTimeout(()=>{
                    $("#preloader").css("display", "none");
                },1000);
            })
        });
    },
    methods: {
        changeTemperatureDegrees(degree) {
            let value;
            this.isCelsius = !this.isCelsius;
            if (this.isCelsius) {
                value = (degree -32) * 5 / 9;
                this.temperature = Math.round(value);
                this.temperatureSign = "°C";
            } else {
                value = degree * 9 / 5 + 32;
                this.temperature = Math.round(value);
                this.temperatureSign = "°F";
            }
        },
        getLocation() {
            return new Promise(resolve => {
                const { geolocation } = navigator
                if (geolocation) {
                    geolocation.getCurrentPosition(this.locationSuccessCallback, this.locationErrorCallback, {enableHighAccuracy: true, timeout: 1000, maximumAge: 0});
                } else {
                    alert("Geolocation is not supported by this browser.");
                }
                resolve();
            })
        },

        locationSuccessCallback(position){
            const lat = position.coords.latitude;
            const lon = position.coords.longitude;
            // const temp = {
            //     "coord":{"lon":28.43,"lat":49.22},
            //     "weather":[{"id":800,"main":"Clear","description":"clear sky","icon":"01d"}],
            //     "base":"stations",
            //     "main":{"temp":18,"pressure":1000,"humidity":59,"temp_min":18,"temp_max":18},
            //     "visibility":10000,
            //     "wind":{"speed":5,"deg":150},
            //     "clouds":{"all":4},
            //     "dt":1572872084,
            //     "sys":{"type":1,"id":8918,"country":"UA","sunrise":1572843481,"sunset":1572878496},
            //     "timezone":7200,
            //     "id":689558,
            //     "name":"Vinnytsya",
            //     "cod":200
            // }
            // this.updateWeather(temp)
            
            this.getWeather(lat,lon).then((response)=>{
                this.updateWeather(response);
            })
        },

        locationErrorCallback(error){
            let errorMessage = 'Unknown error';
            switch(error.code) {
                case 1:
                    errorMessage = 'Permission denied';
                    break;
                case 2:
                    errorMessage = 'Position unavailable';
                    break;
                case 3:
                    errorMessage = 'Timeout';
                    break;
            }
            alert(errorMessage);
        },

        getWeather(lat, lon) {
            return new Promise((resolve, reject) => {
                axios.get(API.url + `weather?lat=${lat}&lon=${lon}&units=metric&appid=${API.key}`).then((response) => {
                    resolve(response.data)
                }).catch((error)=> {
                    if (error.response) {
                        console.log(error.response.data);
                        console.log("Error Status: " + error.response.status);
                        console.log(error.response.headers);
                    } else if (error.request) {
                        console.log(error.request);
                    } else {
                        console.log('Error', error.message);
                    }
                    reject();
                    console.log(error.config);
                });
            });
        },
        updateWeather(response){
            if(response){
                this.weatherData = response;
                const { main: { temp, humidity, pressure }, name, sys: { sunrise, sunset }, wind: { speed, deg }, rain, weather } = this.weatherData;
                this.temperature = Math.round(temp);
                this.city = name;
                this.sunrise = moment.unix(sunrise).format('h:mm:ss');
                this.sunset = moment.unix(sunset).format('h:mm:ss');
                this.humidity = humidity;
                this.pressure = pressure * 0.75;
                this.wind.speed = speed;
                this.wind.deg = deg;
                this.wind.rotation = `transform: rotate3d(0,0,1, ${deg}deg)`;
                this.rain = rain ? rain["rain.1h"] : 0;
                this.weatherAnimations.changeWeather(this.getWeatherType(weather[0].id, weather[0].description));
            }
        },

        getWeatherType(id, description) {
            let weather = {type: 'sun', name: description};

            if (id >= 200 && id <= 232){ //Group 2xx: Thunderstorm
                weather.type = 'thunder';
            }
            else if (id >= 300 && id <= 321){ //Group 3xx: Drizzle
                weather.type = 'rain';
            }
            else if (id >= 500 && id <= 531){//Group 5xx: Rain
                weather.type = 'rain';
            }
            else if (id >= 600 && id <= 622){//Group 6xx: Snow
                if(id >= 612 && id <= 616){
                    weather.type = 'snowRain';
                }else {
                    weather.type = 'snow';
                }
            }
            else if (id >= 701 && id <= 781){//Group 7xx: Atmosphere
                weather.type = 'clouds';
            }
            else if (id === 800) { //Group 800: Clear
                weather.type = 'sun';
            }
            else if (id >= 801 && id <= 804){//Group 80x: Clouds
                weather.type = 'clouds';
            }
            else {
                weather.type = 'sun';
            }
            return weather;
        }
    }
}
